function m(){const t=document.querySelectorAll('input[name="employee_ids"]'),e=document.querySelectorAll('input[name="employee_ids"]:checked'),d=document.getElementById("select-all-employees");let n=gettext("No employees selected");if(d&&d.checked&&e.length===t.length&&e.length>0)n=gettext("Selected all");else{const r=Array.from(e).map(a=>{const o=a.closest("tr");if(o){const s=o.querySelector("td:nth-child(2)");let c="";s&&(c=Array.from(s.childNodes).filter(l=>l.nodeType===Node.TEXT_NODE&&l.textContent.trim()).map(l=>l.textContent.trim())[0]||"");const i=o.querySelector("td:nth-child(3)")?.textContent.trim()||"";return c&&i?`${c}/${i}`:""}return""}).filter(Boolean);r.length&&(n=r.join(", "))}document.getElementById("selected-employees-list").textContent=n;const u=document.querySelectorAll('input[name="work_ids"]:checked');document.getElementById("selected-summary").style.display=e.length||u.length?"":"none"}document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll('input[name="employee_ids"]').forEach(e=>{e.addEventListener("change",m)});const t=document.getElementById("select-all-employees");t&&t.addEventListener("change",m),m()});
